-- Hosbah: an S3 bucket of a git-deployed site (app) on one of the team's MinIO data services, with
-- an access key whose MinIO policy reaches that one bucket only. secret_sealed is the key's secret,
-- sealed with the team DEK and bound to (service, bucket) — it is never returned by the API; the
-- app receives it as the sealed env var <env_prefix>_SECRET_ACCESS_KEY. status: creating (the
-- agent's bucket.create is going) → ready | failed; removing while bucket.remove runs. A bucket
-- name is unique per service. Rows go with their app; a data service that still has app buckets
-- cannot be deleted (RESTRICT) — the keys and env vars would silently dangle otherwise.
ALTER TABLE app_buckets ADD CONSTRAINT app_buckets_bucket_check CHECK (bucket ~ '^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$');
ALTER TABLE app_buckets ADD CONSTRAINT app_buckets_access_key_check CHECK (access_key ~ '^[A-Za-z0-9]{8,20}$');
ALTER TABLE app_buckets ADD CONSTRAINT app_buckets_env_prefix_check CHECK (env_prefix ~ '^[A-Z][A-Z0-9_]{0,20}$');
ALTER TABLE app_buckets ADD CONSTRAINT app_buckets_status_check CHECK (status IN ('creating', 'ready', 'failed', 'removing'));
CREATE UNIQUE INDEX app_buckets_service_bucket_key ON app_buckets (service_id, bucket);
CREATE UNIQUE INDEX app_buckets_app_prefix_key ON app_buckets (app_id, env_prefix);
CREATE UNIQUE INDEX app_buckets_id_team_key ON app_buckets (id, team_id);
CREATE INDEX app_buckets_team_idx ON app_buckets (team_id);
CREATE INDEX app_buckets_app_idx ON app_buckets (app_id);
